mapper.select:
SELECT distinct A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, CONCAT_WS('',A.FINPROD_ID , ',' , D.IS_LAY ,',' ,A.FINPROD_ABBR) object FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT A1 ON A.FINPROD_ID = A1.p_Finprod_Id INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID INNER JOIN FIN_CASH_INFO C ON (A.FINPROD_ID = C.FINPROD_ID OR A.P_FINPROD_ID = C.FINPROD_ID) INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID and D.issue_status = #{ISSUE_STATUS_01} WHERE A.FINPROD_ID = C.FINPROD_ID
AND EXISTS( SELECT * FROM FIN_CASH_INFO C WHERE C.CASH_TYPE_1=#{CASH_TYPE_1_06,jdbcType=VARCHAR} AND (A.FINPROD_ID = C.FINPROD_ID OR A1.FINPROD_ID = C.FINPROD_ID) )
AND ( A.FINPROD_MARKET_ID LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') or A.FINPROD_ABBR LIKE CONCAT('%',#{search,jdbcType=VARCHAR},'%') )
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}
and A.FINPROD_MARKET_ID = #{initValue}

select @rownum:=@rownum+1 as rn, (CASE WHEN fin_product_add.is_lay =#{YES_OR_NO_NO} THEN B.Finprod_id ELSE B1.finprod_id END) finprodId, B.Finprod_Market_id finprodMarketId, (CASE WHEN fin_product_add.is_lay =#{YES_OR_NO_NO} THEN B.Finprod_abbr ELSE B1.Finprod_abbr END) finprodAbbr, fin_product_add.is_lay isLay, lay.prod_style prodStyle, lay.finprod_id layFinprodId, A.cash_id cashId, A.ACCR_DATE accrDate, ACCR_STR_DATE accrStrDate, ACCR_END_DATE accrEndDate, VAL_DATE valDate, case when (select count(1) from (select finprod_id finprod_id, happen_date trade_date from BOK_CLAWBACK_INFO_DETAIL where bookset_id = #{finprodId,jdbcType = VARCHAR} union all select deal.finprod_id,total.trade_date from trd_fin_product_deal_total total left join TRD_PRODUCT_DEAL deal on total.TOTLE_TRADE_ID = deal.TOTLE_TRADE_ID where total.finprod_id = #{finprodId,jdbcType = VARCHAR} and (total.is_cancel = #{YES_OR_NO_NO} or total.is_cancel is null) and total.trade_status = #{TRADE_STATUS_01} and total.ps = #{PS_C16}) D where D.finprod_id = B.finprod_id and D.trade_date = A.accr_date) > 0 then #{SUPPLEMENT_STATUS_01} else #{SUPPLEMENT_STATUS_02} end supplementStatus, #{YES_OR_NO_YES} isAvailable from (SELECT @rownum:=0) r, fin_float_accrual_sche A inner join fin_cash_info C on A.cash_id = C.cash_id inner join fin_product B on (c.finprod_id = B.finprod_id or c.finprod_id = B.p_Finprod_Id) inner join fin_product_add on B.finprod_id = fin_product_add.finprod_id left join prd_layer_param lay on B.finprod_id = lay.finprod_id left join fin_product B1 on B1.FINPROD_ID = B.P_FINPROD_ID where (B.finprod_id = #{finprodId,jdbcType = VARCHAR} or B.P_FINPROD_ID = #{finprodId,jdbcType = VARCHAR}) and C.Cash_Type_1 = #{CASH_TYPE_1_06, jdbcType = VARCHAR}
and lay.finprod_id in
#{item}
order by lay.prod_style,ACCR_STR_DATE
